describe('Async Error Handling', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should display a retry option when an async error occurs', () => {
        cy.intercept('GET', '/api/data', {
            statusCode: 500,
            body: { error: 'Internal Server Error' },
        }).as('getData');

        cy.get('button.fetch-data').click(); // Trigger the async operation
        cy.wait('@getData');

        cy.get('.error-message').should('be.visible');
        cy.get('.retry-button').should('be.visible').and('contain', 'Retry');
    });

    it('should retry the async operation when the retry option is clicked', () => {
        cy.intercept('GET', '/api/data', {
            statusCode: 500,
            body: { error: 'Internal Server Error' },
        }).as('getData');

        cy.get('button.fetch-data').click(); // Trigger the async operation
        cy.wait('@getData');

        cy.get('.retry-button').click(); // Click the retry option

        cy.intercept('GET', '/api/data', {
            statusCode: 200,
            body: { data: 'Success' },
        }).as('getDataSuccess');

        cy.wait('@getDataSuccess');

        cy.get('.success-message').should('be.visible').and('contain', 'Success');
    });
});
